  urlEl.addEventListener('input', refreshButton);
  urlEl.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); save(); } });
  saveEl.addEventListener('click', save);

  // ---- events: list (delegated) --------------------------------------------
  listEl.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'showmore') { visibleCount += (pageSize || 0); render(); return; }
    if (t.dataset.edit) { editingId = Number(t.dataset.edit); openTagEditor = null; render(); flash(editingId); }
    else if (t.dataset.cancelEdit) { editingId = null; render(); }
    else if (t.dataset.saveEdit) {
      var id = Number(t.dataset.saveEdit), box = t.closest('.edit');
      var nu = U.normalize(box.querySelector('[data-f=url]').value);
      if (!nu) { toast('A web address is required.'); return; }
      if (!U.isValid(nu)) { toast('That doesn’t look like a web address.'); return; }
      var payload = {
        title: box.querySelector('[data-f=title]').value.trim() || byId(id).title,
        url: nu,
        description: box.querySelector('[data-f=description]').value.trim(),
        note: box.querySelector('[data-f=note]').value.trim()
      };
      api('PATCH', '/api/bookmarks/' + id, payload).then(function (r) {
        if (r.status === 409) { editingId = null; render(); flash(r.body.existingId); toast('Another bookmark already uses that address — showing it.'); return; }
        if (r.body.bookmark) replaceBookmark(r.body.bookmark);
        editingId = null; render(); flash(id); toast('Changes saved.');
      });
    }
    else if (t.dataset.delete) {
      var did = Number(t.dataset.delete), b = byId(did);
      if (confirm('Delete “' + b.title + '” permanently? This cannot be undone.')) {
        api('DELETE', '/api/bookmarks/' + did).then(function () { state.bookmarks = state.bookmarks.filter(function (x) { return x.id !== did; }); editingId = null; pruneTags(); render(); toast('Bookmark deleted permanently.'); });
      }
    }
    else if (t.dataset.rm) { var p = t.dataset.rm.split('|'); var rid = Number(p[0]); var bk = byId(rid); var next = bk.tags.filter(function (x) { return x !== p[1]; }); api('PATCH', '/api/bookmarks/' + rid, { tags: next }).then(function (r) { if (r.body.bookmark) replaceBookmark(r.body.bookmark); pruneTags(); render(); }); }
    else if (t.dataset.add) { openTagEditor = Number(t.dataset.add); render(); }
    else if (t.dataset.pick) { addTagTo(openTagEditor, t.dataset.pick); }
    else if (t.dataset.read) { var rd = Number(t.dataset.read), bb = byId(rd); api('PATCH', '/api/bookmarks/' + rd, { read: !bb.read }).then(function (r) { if (r.body.bookmark) replaceBookmark(r.body.bookmark); render(); if ($('item-' + rd)) flash(rd); toast(!bb.read ? 'Marked as read.' : 'Marked as still to read.'); }); }
    else if (t.dataset.archive) { var ar = Number(t.dataset.archive), ab = byId(ar); api('PATCH', '/api/bookmarks/' + ar, { archived: !ab.archived }).then(function (r) { if (r.body.bookmark) replaceBookmark(r.body.bookmark); editingId = null; render(); toast(!ab.archived ? 'Archived — moved out of your main list.' : 'Restored to your list.'); }); }
    else if (t.dataset.snap) { doSnapshot(Number(t.dataset.snap)); }
    else if (t.dataset.snapRemove) { var srid = Number(t.dataset.snapRemove); api('DELETE', '/api/bookmarks/' + srid + '/snapshot').then(function () { var bm = byId(srid); bm.snapshot = null; render(); toast('Saved copy removed.'); }); }
    else if (t.dataset.wayback) { doWayback(Number(t.dataset.wayback)); }
  });
  listEl.addEventListener('input', function (e) { if (e.target.dataset.taginput) updateSuggest(Number(e.target.dataset.taginput), e.target.value); });
  listEl.addEventListener('keydown', function (e) { if (!e.target.dataset.taginput) return; var id = Number(e.target.dataset.taginput); if (e.key === 'Enter') { e.preventDefault(); addTagTo(id, e.target.value); } else if (e.key === 'Escape') { openTagEditor = null; render(); } });
  listEl.addEventListener('change', function (e) { if (e.target.dataset.sel) { var id = Number(e.target.dataset.sel); if (e.target.checked) selected.add(id); else selected.delete(id); var c = $('item-' + id); if (c) c.classList.toggle('selected', e.target.checked); updateBulkbar(); } });
  document.addEventListener('click', function (e) { if (openTagEditor !== null && !e.target.closest('.tag-editor') && !e.target.dataset.add) { openTagEditor = null; render(); } });

  function doSnapshot(id) {
    var b = byId(id); toast(b.isPdf ? 'Saving the PDF…' : 'Saving a copy…');
    api('POST', '/api/bookmarks/' + id + '/snapshot').then(function (r) {
      if (r.status === 200) { b.snapshot = r.body.snapshot; render(); toast(b.isPdf ? 'PDF saved for offline viewing.' : 'A copy of this page was saved.'); }
      else { toast(r.body.error || 'Could not save a copy. You can retry.'); }
    });
  }
  function doWayback(id) {
    var b = byId(id); toast('Requesting Internet Archive…');
    api('POST', '/api/bookmarks/' + id + '/wayback').then(function (r) {
      if (r.status === 200) { b.wayback = r.body.wayback; render(); toast('Preserved via the Internet Archive.'); }
      else { toast(r.body.error || 'Internet Archive preservation failed. You can retry.'); }
    });
  }

  // ---- status / tags / search / controls -----------------------------------
  statusbarEl.addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; statusView = b.dataset.view; visibleCount = pageSize; render(); });
  tagbarEl.addEventListener('click', function (e) {
    var b = e.target.closest('button'); if (!b) return;
    if (b.dataset.clear) { incTags = []; excTags = []; }
    else { var t = b.dataset.t, iI = incTags.indexOf(t), iE = excTags.indexOf(t); if (iI < 0 && iE < 0) incTags.push(t); else if (iI >= 0) { incTags.splice(iI, 1); excTags.push(t); } else excTags.splice(iE, 1); }
    visibleCount = pageSize; render();
  });
  searchEl.addEventListener('input', function () { query = searchEl.value.trim(); visibleCount = pageSize; render(); });

  var sortsel = $('sortsel'), pagesel = $('pagesel'), setdefault = $('setdefault');
  function markDirty() { setdefault.textContent = 'Set as my default'; setdefault.classList.remove('saved'); }
  sortsel.addEventListener('change', function () { sortBy = sortsel.value; visibleCount = pageSize; markDirty(); render(); });
  pagesel.addEventListener('change', function () { pageSize = parseInt(pagesel.value, 10); visibleCount = pageSize; markDirty(); render(); });
  setdefault.addEventListener('click', function () { api('PUT', '/api/settings', { sort: sortBy, pageSize: pageSize, textSize: textSize }).then(function (r) { state.settings = r.body.settings; setdefault.textContent = 'Saved as default ✓'; setdefault.classList.add('saved'); toast('These settings are now your default.'); }); });
  $('textup').addEventListener('click', function () { textSize = textSize === 's' ? 'm' : 'l'; markDirty(); render(); });
  $('textdown').addEventListener('click', function () { textSize = textSize === 'l' ? 'm' : 's'; markDirty(); render(); });

  // ---- saved views ---------------------------------------------------------
  $('saveview').addEventListener('click', function () {
    if (!query && !incTags.length && !excTags.length) { toast('Set a search and/or tag filters first, then save the view.'); return; }
    var name = prompt('Name this view:'); if (!name) return; name = name.trim(); if (!name) return;
    api('POST', '/api/views', { name: name, query: query, inc: incTags.slice(), exc: excTags.slice() }).then(function (r) { state.views = r.body.views; render(); toast('View “' + name + '” saved.'); });
  });
  $('viewchips').addEventListener('click', function (e) {
    if (e.target.dataset.viewDel !== undefined) { e.stopPropagation(); var i = Number(e.target.dataset.viewDel); var nm = state.views[i].name; api('DELETE', '/api/views/' + encodeURIComponent(nm)).then(function (r) { state.views = r.body.views; render(); toast('View “' + nm + '” removed.'); }); return; }
    var c = e.target.closest('[data-view-apply]'); if (c) { var v = state.views[Number(c.dataset.viewApply)]; query = v.query || ''; searchEl.value = query; incTags = (v.inc || []).slice(); excTags = (v.exc || []).slice(); visibleCount = pageSize; render(); }
  });

  // ---- bulk ----------------------------------------------------------------
  function selectedItems() { var a = []; selected.forEach(function (id) { var b = byId(id); if (b) a.push(b); }); return a; }
  function updateBulkbar() {
    var n = selected.size, matchN = lastShownIds.length;
    var allSel = matchN > 0 && lastShownIds.every(function (id) { return selected.has(id); });
    $('selectall-top').textContent = allSel && matchN > 0 ? 'Clear selection' : 'Select all ' + matchN + ' matching';
    bulkbarEl.hidden = n === 0; if (n === 0) return;
    $('bulkcount').textContent = n + ' selected';
    $('selectall').textContent = allSel ? 'Clear all ' + matchN + ' matching' : 'Select all ' + matchN + ' matching';
    var inArchive = statusView === 'archived';
    $('bulk-arch').textContent = inArchive ? 'Restore' : 'Archive';
    $('bulk-read').style.display = inArchive ? 'none' : '';
    $('bulk-unread').style.display = inArchive ? 'none' : '';
  }
  function toggleSelectAll() { var matchN = lastShownIds.length; var allSel = matchN > 0 && lastShownIds.every(function (id) { return selected.has(id); }); if (allSel) lastShownIds.forEach(function (id) { selected.delete(id); }); else lastShownIds.forEach(function (id) { selected.add(id); }); render(); }
  $('selectall').addEventListener('click', toggleSelectAll);
  $('selectall-top').addEventListener('click', toggleSelectAll);
  $('bulk-clear').addEventListener('click', function () { selected.clear(); closeBulkTag(); render(); });
  function bulk(action, extra) {
    var ids = selectedItems().map(function (b) { return b.id; }); if (!ids.length) return Promise.resolve();
    var body = Object.assign({ ids: ids, action: action }, extra || {});
    return api('POST', '/api/bookmarks/bulk', body).then(function (r) { if (r.body.state) state = r.body.state; return r; });
  }
  function openBulkTag(mode) { bulkTagMode = mode; $('bulk-taglist').innerHTML = allTags().map(function (t) { return '<option value="' + esc(t) + '">'; }).join(''); $('bulk-taginput').hidden = false; $('bulk-tag-mode').textContent = (mode === 'add' ? 'Add this tag to ' : 'Remove this tag from ') + selected.size + ' bookmarks'; var f = $('bulk-tagfield'); f.value = ''; f.focus(); }
  function closeBulkTag() { $('bulk-taginput').hidden = true; bulkTagMode = null; }
  function applyBulkTag() { var t = $('bulk-tagfield').value.trim().toLowerCase().replace(/^#/, ''); if (!t) return; var mode = bulkTagMode; bulk(mode === 'add' ? 'addTag' : 'removeTag', { tag: t }).then(function (r) { pruneTags(); closeBulkTag(); render(); toast((mode === 'add' ? 'Tagged ' : 'Untagged ') + (r.body.count || 0) + ' bookmark(s) “#' + t + '”.'); }); }
  $('bulk-tag-add').addEventListener('click', function () { openBulkTag('add'); });
  $('bulk-tag-rm').addEventListener('click', function () { openBulkTag('remove'); });
  $('bulk-tag-cancel').addEventListener('click', closeBulkTag);
  $('bulk-tag-apply').addEventListener('click', applyBulkTag);
  $('bulk-tagfield').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); applyBulkTag(); } });
  $('bulk-read').addEventListener('click', function () { var n = selected.size; bulk('read').then(function () { render(); toast('Marked ' + n + ' as read.'); }); });
  $('bulk-unread').addEventListener('click', function () { var n = selected.size; bulk('unread').then(function () { render(); toast('Marked ' + n + ' as to read.'); }); });
  $('bulk-arch').addEventListener('click', function () { var restore = statusView === 'archived', n = selected.size; bulk(restore ? 'restore' : 'archive').then(function () { selected.clear(); render(); toast((restore ? 'Restored ' : 'Archived ') + n + ' bookmark(s).'); }); });
  $('bulk-del').addEventListener('click', function () { var n = selected.size; if (confirm('Delete ' + n + ' bookmark(s) permanently? This cannot be undone.')) { bulk('delete').then(function () { selected.clear(); pruneTags(); render(); toast(n + ' bookmark(s) deleted permanently.'); }); } });

  // ---- import / export -----------------------------------------------------
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>My Bookmarks</title>
<link rel="stylesheet" href="style.css" />
</head>
<body>
<header class="apphead">
  <h1>My Bookmarks</h1>
  <div class="head-actions">
    <button class="ghost" id="importbtn">Import…</button>
    <button class="ghost" id="exportbtn">Export</button>
    <input type="file" id="importfile" accept=".html,.htm,text/html" hidden />
  </div>
</header>

<main>
  <section class="capture">
    <label for="url">Paste a link to save</label>
    <input id="url" type="text" placeholder="https://…" autocomplete="off" />
    <div class="row">
      <button id="save" class="primary" disabled>Save link</button>
      <span class="hint" id="cap-hint">Enter a link to enable saving.</span>
    </div>
  </section>

  <div class="statusbar" id="statusbar" hidden>
    <button class="pill active" data-view="all">All</button>
    <button class="pill" data-view="unread">To read <span class="badge-n" id="n-unread"></span></button>
    <button class="pill" data-view="read">Read <span class="badge-n" id="n-read"></span></button>
    <button class="pill archived-pill" data-view="archived">Archive <span class="badge-n" id="n-arch"></span></button>
  </div>

  <div class="searchbar" id="searchbar" hidden>
    <input id="search" type="search" placeholder="Search your bookmarks…" autocomplete="off" />
    <p class="searchhelp">Try <code>#tag</code>, <code>"exact phrase"</code>, or <code>space AND (#article OR #video)</code>.</p>
  </div>

  <div class="controls" id="controls" hidden>
    <label class="ctl">Sort
      <select id="sortsel">
        <option value="new">Newest first</option>
        <option value="updated">Recently updated</option>
        <option value="old">Oldest first</option>
        <option value="az">Title A–Z</option>
        <option value="za">Title Z–A</option>
      </select>
    </label>
    <label class="ctl">Show
      <select id="pagesel">
        <option value="10">10</option>
        <option value="25">25</option>
        <option value="50">50</option>
        <option value="0">All</option>
      </select>
    </label>
    <button class="ctl-link" id="selectall-top">Select all matching</button>
    <button class="ctl-link" id="setdefault">Set as my default</button>
    <span class="ctl-group">Text
      <button class="ctl-btn" id="textdown" aria-label="Smaller text">A−</button>
      <button class="ctl-btn" id="textup" aria-label="Larger text">A+</button>
    </span>
  </div>

  <div class="viewsbar" id="viewsbar" hidden>
    <span class="lbl">Saved views</span>
    <span id="viewchips"></span>
    <button class="ctl-link" id="saveview">＋ Save current view</button>
  </div>

  <div class="filterbar" id="filterbar" hidden>
    <span class="lbl">Filter by tag — tap to include, again to exclude, again to clear</span>
    <div id="tagbar"></div>
  </div>

  <p class="list-head" id="listhead">Saved links</p>
  <div id="list"></div>
</main>

<div class="bulkbar" id="bulkbar" hidden>
  <div class="bulkbar-inner">
    <span class="bulk-count" id="bulkcount">0 selected</span>
    <button class="ghost" id="selectall">Select all matching</button>
    <button class="ghost" id="bulk-tag-add">Add tag</button>
    <button class="ghost" id="bulk-tag-rm">Remove tag</button>
    <button class="ghost" id="bulk-read">Mark read</button>
    <button class="ghost" id="bulk-unread">Mark unread</button>
    <button class="ghost" id="bulk-arch">Archive</button>
    <button class="danger" id="bulk-del">Delete</button>
    <button class="ghost" id="bulk-clear">Clear</button>
  </div>
  <div class="bulk-taginput" id="bulk-taginput" hidden>
    <input id="bulk-tagfield" list="bulk-taglist" placeholder="tag name…" autocomplete="off" />
    <datalist id="bulk-taglist"></datalist>
    <button class="primary" id="bulk-tag-apply">Apply</button>
    <button class="ghost" id="bulk-tag-cancel">Cancel</button>
    <span class="hint" id="bulk-tag-mode"></span>
  </div>
</div>

<div class="toast" id="toast"></div>

<script src="/lib/urls.js"></script>
<script src="/lib/query.js"></script>
<script src="app.js"></script>
</body>
</html>
:root { --bg:#f5f6f8; --card:#fff; --line:#e4e6eb; --ink:#1c1e21; --sub:#65676b; --accent:#2f6fed; }
* { box-sizing:border-box; }
body { margin:0; font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
       background:var(--bg); color:var(--ink); }
header { background:var(--card); border-bottom:1px solid var(--line); padding:14px 20px; }
.apphead { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.apphead h1 { margin:0; font-size:18px; }
.head-actions { display:flex; gap:8px; }
main { max-width:760px; margin:0 auto; padding:20px 16px 130px; }

.capture { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; margin-bottom:18px; }
.capture label { display:block; font-size:13px; color:var(--sub); margin:0 0 4px; }
.capture input { width:100%; padding:11px 12px; border:1px solid var(--line); border-radius:9px; font-size:15px; }
.capture input:focus, .searchbar input:focus, .edit input:focus, .edit textarea:focus,
.tag-input:focus, .bulk-taginput input:focus { outline:none; border-color:var(--accent); }
.row { display:flex; gap:10px; align-items:center; margin-top:12px; }
button.primary { background:var(--accent); color:#fff; border:0; border-radius:9px; padding:11px 18px; font-size:15px; cursor:pointer; }
button.primary:disabled { opacity:.5; cursor:not-allowed; }
button.ghost { background:transparent; border:1px solid var(--line); border-radius:8px; padding:7px 12px; font-size:13px; cursor:pointer; color:var(--ink); }
button.danger { background:transparent; border:1px solid #e2b4b4; border-radius:8px; padding:7px 12px; font-size:13px; cursor:pointer; color:#b42318; margin-left:auto; }
button.danger:hover { background:#fdeaea; }
.hint { font-size:12px; color:var(--sub); }

.statusbar { margin:0 0 12px; display:flex; flex-wrap:wrap; align-items:center; gap:6px; }
.pill { background:#eef1f6; border:0; border-radius:20px; padding:6px 13px; font-size:13px; cursor:pointer; color:var(--ink); }
.pill.active { background:var(--accent); color:#fff; }
.pill.inc { background:var(--accent); color:#fff; }
.pill.exc { background:#fdeaea; color:#b42318; border:1px solid #e2b4b4; text-decoration:line-through; }
.badge-n { font-size:11px; opacity:.8; margin-left:2px; }
.archived-pill { margin-left:auto; }

.searchbar { margin:0 0 12px; }
.searchbar input { width:100%; padding:11px 14px; border:1px solid var(--line); border-radius:9px; font-size:15px; background:var(--card); }
.searchhelp { font-size:12px; color:var(--sub); margin:6px 2px 0; }
.searchhelp code { background:#eef1f6; padding:1px 5px; border-radius:4px; }
mark { background:#fff2a8; color:inherit; border-radius:2px; }

.controls { display:flex; flex-wrap:wrap; align-items:center; gap:12px; margin:0 0 14px; font-size:13px; color:var(--sub); }
.controls .ctl { display:inline-flex; align-items:center; gap:6px; }
.controls select { padding:6px 8px; border:1px solid var(--line); border-radius:7px; font-size:13px; background:var(--card); }
.ctl-link { background:none; border:0; color:var(--accent); cursor:pointer; font-size:13px; padding:0; }
.ctl-link.saved { color:#2e7d32; }
.ctl-group { display:inline-flex; align-items:center; gap:5px; margin-left:auto; }
.ctl-btn { border:1px solid var(--line); background:var(--card); border-radius:7px; cursor:pointer; padding:4px 9px; font-size:13px; }

.viewsbar { margin:0 0 12px; display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
.lbl { font-size:12px; color:var(--sub); text-transform:uppercase; letter-spacing:.04em; }
.view-chip { display:inline-flex; align-items:center; gap:6px; background:#eef1f6; border:1px solid var(--line); border-radius:16px; padding:5px 6px 5px 12px; font-size:13px; cursor:pointer; color:var(--ink); }
.view-chip.active { background:var(--accent); color:#fff; border-color:var(--accent); }
.view-chip .vx { cursor:pointer; opacity:.75; padding:0 4px; }

.filterbar { margin:0 0 14px; }
.filterbar .lbl { display:block; margin-bottom:7px; }
#tagbar .pill { margin:0 6px 6px 0; }

.list-head { font-size:13px; color:var(--sub); margin:6px 0 10px; text-transform:uppercase; letter-spacing:.04em; }

#list.ts-s { font-size:13px; } #list.ts-m { font-size:15px; } #list.ts-l { font-size:17px; }

.item { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:0; margin-bottom:12px; overflow:hidden; transition:box-shadow .3s; }
.item.flash { box-shadow:0 0 0 3px rgba(47,111,237,.45); }
.item.selected { box-shadow:0 0 0 2px var(--accent) inset; }
.item.is-read { opacity:.72; }
.item.is-read .title a { color:var(--sub); }
.item.is-archived { opacity:.85; border-style:dashed; }
.item .preview { width:100%; height:150px; object-fit:cover; display:block; background:#eef1f6; }
.item .content { padding:14px 16px; display:flex; gap:12px; align-items:flex-start; }
.selbox { width:17px; height:17px; margin:2px 0 0; flex:0 0 auto; cursor:pointer; }
.fav { width:28px; height:28px; border-radius:7px; background:#eef1f6; flex:0 0 auto; display:flex; align-items:center; justify-content:center; font-size:15px; overflow:hidden; }
.fav img { width:100%; height:100%; object-fit:cover; }
.item .body { min-width:0; flex:1; }
.item .title { font-size:1.02em; font-weight:600; margin:0 0 3px; word-break:break-word; }
.item .title a { color:var(--ink); text-decoration:none; }
.item .title a:hover { text-decoration:underline; }
.unread-badge { display:inline-block; background:#ffe1b3; color:#8a5a00; font-size:11px; font-weight:600; padding:1px 7px; border-radius:10px; margin-left:8px; vertical-align:middle; }
.item .desc { font-size:.9em; color:#3a3c40; margin:0 0 6px; }
.pdf-tag { display:inline-block; background:#d9364420; color:#b42318; font-size:11px; font-weight:600; padding:0 5px; border-radius:4px; }
.item .url { font-size:12px; color:var(--sub); word-break:break-all; margin:0; }
.item .meta { font-size:12px; color:var(--sub); margin-top:6px; }
.offline-badge { font-size:12px; color:var(--sub); margin:6px 0 0; }
.offline-badge a { color:var(--accent); text-decoration:none; }

.note-line { font-size:.9em; color:#3a3c40; margin:9px 0 0; background:#fff8e1; border-left:3px solid #f0d478; padding:6px 10px; border-radius:0 6px 6px 0; display:flex; gap:6px; }
.note-pin { color:#b7930f; }
.note-md { min-width:0; flex:1; }
.note-md > :first-child { margin-top:0; } .note-md > :last-child { margin-bottom:0; }
.note-md h1,.note-md h2,.note-md h3,.note-md h4 { font-size:1em; margin:8px 0 4px; }
.note-md p { margin:6px 0; }
.note-md ul,.note-md ol { margin:6px 0; padding-left:20px; }
.note-md code { background:#eceff3; padding:1px 5px; border-radius:4px; font-size:.9em; }
.note-md pre { background:#eceff3; padding:8px 10px; border-radius:7px; overflow:auto; margin:6px 0; }
.note-md pre code { background:none; padding:0; }
.note-md a { color:var(--accent); }

.chips { margin-top:9px; display:flex; flex-wrap:wrap; align-items:center; gap:6px; position:relative; }
.chip { display:inline-flex; align-items:center; background:#eef1f6; border-radius:16px; padding:3px 5px 3px 10px; font-size:12px; color:#333; }
.chip .x { cursor:pointer; margin-left:4px; color:var(--sub); padding:0 4px; }
.chip.add { background:transparent; border:1px dashed var(--line); cursor:pointer; color:var(--sub); padding:3px 10px; }
.tag-editor { display:inline-flex; align-items:center; position:relative; }
.tag-input { border:1px solid var(--accent); border-radius:16px; padding:3px 9px; font-size:12px; width:130px; }
.suggest { position:absolute; top:100%; left:0; margin-top:4px; background:#fff; border:1px solid var(--line); border-radius:9px; box-shadow:0 6px 20px rgba(0,0,0,.12); z-index:5; min-width:150px; overflow:hidden; }
.suggest div { padding:8px 11px; font-size:13px; cursor:pointer; }
.suggest div:hover { background:#eef1f6; }
.suggest .new { color:var(--accent); }

.actions { margin-top:10px; display:flex; flex-wrap:wrap; gap:6px; }
.edit { padding:14px 16px; border-top:1px solid var(--line); background:#fafbfc; }
.edit label { display:block; font-size:12px; color:var(--sub); margin:0 0 4px; }
.edit input, .edit textarea { width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:8px; font-size:14px; margin-bottom:10px; font-family:inherit; }
.edit textarea { resize:vertical; min-height:56px; }
.offline { border-top:1px dashed var(--line); margin:2px 0 12px; padding-top:10px; }
.offline-title { font-size:12px; color:var(--sub); text-transform:uppercase; letter-spacing:.04em; margin-bottom:6px; }
.offline-line { font-size:13px; margin:6px 0; color:#3a3c40; }
.offline-line a { color:var(--accent); }
.danger-link { color:#b42318; background:none; border:0; cursor:pointer; font-size:13px; padding:0; }

.empty { text-align:center; color:var(--sub); padding:40px 10px; }
.arch-note { background:#fff8e1; border:1px solid #f2e2a8; border-radius:10px; padding:11px 14px; font-size:13px; color:#5a4b16; margin-bottom:16px; }
.showmore { display:block; width:100%; margin:4px 0 10px; padding:10px; border:1px dashed var(--line); background:var(--card); border-radius:9px; cursor:pointer; font-size:14px; color:var(--accent); }

.bulkbar { position:fixed; left:0; right:0; bottom:0; background:var(--card); border-top:1px solid var(--line); box-shadow:0 -4px 18px rgba(0,0,0,.08); z-index:20; }
.bulkbar-inner { max-width:760px; margin:0 auto; padding:10px 16px; display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
.bulk-count { font-weight:600; font-size:14px; margin-right:4px; }
.bulk-taginput { max-width:760px; margin:0 auto; padding:0 16px 12px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }
.bulk-taginput input { padding:8px 11px; border:1px solid var(--accent); border-radius:8px; font-size:14px; }

.toast { position:fixed; left:50%; bottom:84px; transform:translateX(-50%); background:#1c1e21; color:#fff; padding:10px 16px; border-radius:9px; font-size:14px; opacity:0; transition:opacity .2s; pointer-events:none; max-width:90%; text-align:center; z-index:30; }
.toast.show { opacity:1; }

@media (max-width:480px){ .row{flex-wrap:wrap;} button.primary{width:100%;} }
