'use strict';
var test = require('node:test');
var assert = require('node:assert');
var Q = require('../lib/query');

var items = [
  { title: 'Mars Exploration', description: 'rovers and orbiters', note: '', url: 'https://nasa.gov/mars', tags: ['space', 'to-read'] },
  { title: 'Python Decorators', description: 'wrap functions', note: 'read before meeting', url: 'https://realpython.com/dec', tags: ['python', 'to-read'] },
  { title: 'Perfect Pasta', description: 'cook pasta properly', note: '', url: 'https://seriouseats.com/pasta', tags: ['cooking'] }
];
function run(q) { return items.filter(function (it) { return Q.matches(it, q); }); }

test('case-insensitive word match', function () {
  assert.equal(run('PASTA').length, 1);
  assert.equal(run('pasta').length, 1);
});
test('multiple bare words require all', function () {
  assert.equal(run('cook pasta').length, 1);
  assert.equal(run('cook rovers').length, 0);
});
test('#tag matches tag only', function () {
  assert.equal(run('#python').length, 1);
  assert.equal(run('#to-read').length, 2);
});
test('exact phrase', function () {
  assert.equal(run('"perfect pasta"').length, 1);
  assert.equal(run('"pasta perfect"').length, 0);
});
test('boolean OR / NOT / grouping', function () {
  assert.equal(run('#python OR #cooking').length, 2);
  assert.equal(run('NOT #to-read').length, 1);
  assert.equal(run('rovers AND (#space OR #cooking)').length, 1);
});
test('operators are case-insensitive', function () {
  assert.equal(run('#python or #cooking').length, 2);
});
test('quoted operator is literal', function () {
  // "and" appears in "rovers and orbiters"
  assert.equal(run('"and"').length, 1);
});
test('note is searched', function () {
  assert.equal(run('meeting').length, 1);
});
test('malformed query falls back to plain words', function () {
  // unbalanced paren -> plain search of meaningful words -> "python"
  assert.equal(run('((#python').length, 1);
});
test('terms() returns highlightable words, not tags', function () {
  var t = Q.terms('#python pasta "cook it"');
  assert.ok(t.indexOf('pasta') >= 0);
  assert.ok(t.indexOf('cook it') >= 0);
  assert.ok(t.indexOf('python') < 0);
});
'use strict';
var test = require('node:test');
var assert = require('node:assert');
var bf = require('../lib/bookmarkfile');

var SAMPLE = [
  '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
  '<H1>Bookmarks</H1>',
  '<DL><p>',
  '  <DT><H3>Bookmarks bar</H3>',
  '  <DL><p>',
  '    <DT><H3>Programming</H3>',
  '    <DL><p>',
  '      <DT><H3>Python</H3>',
  '      <DL><p>',
  '        <DT><A HREF="https://ex.com/py" ADD_DATE="1600000000" TAGS="reference">Py &amp; more</A>',
  '        <DD>a note',
  '      </DL><p>',
  '    </DL><p>',
  '    <DT><A HREF="https://ex.com/root" ADD_DATE="1500000000">Root page</A>',
  '  </DL><p>',
  '</DL><p>'
].join('\n');

test('parse: titles, saved dates, tags', function () {
  var out = bf.parse(SAMPLE);
  assert.equal(out.length, 2);
  var py = out.find(function (x) { return x.url === 'https://ex.com/py'; });
  assert.equal(py.title, 'Py & more');
  assert.equal(py.addDate, 1600000000 * 1000);
  assert.equal(py.note, 'a note');
});
test('parse: nested folders become tags, generic containers excluded', function () {
  var out = bf.parse(SAMPLE);
  var py = out.find(function (x) { return x.url === 'https://ex.com/py'; });
  assert.deepEqual(py.tags.sort(), ['programming', 'python', 'reference'].sort());
  assert.ok(py.tags.indexOf('bookmarks bar') < 0);
});
test('parse: root-level page has no folder tags', function () {
  var out = bf.parse(SAMPLE);
  var root = out.find(function (x) { return x.url === 'https://ex.com/root'; });
  assert.deepEqual(root.tags, []);
});
test('generate then parse round-trips title/tags/date', function () {
  var bms = [{ url: 'https://a.com/x', title: 'Hello', tags: ['t1', 't2'], note: 'n', saved: 1600000000000, updated: 1600000000000 }];
  var file = bf.generate(bms);
  assert.ok(file.indexOf('TAGS="t1,t2"') >= 0);
  var out = bf.parse(file);
  assert.equal(out.length, 1);
  assert.equal(out[0].title, 'Hello');
  assert.deepEqual(out[0].tags.sort(), ['t1', 't2']);
  assert.equal(out[0].addDate, 1600000000000);
});
'use strict';
var test = require('node:test');
var assert = require('node:assert');
var meta = require('../lib/metadata');
var urls = require('../lib/urls');

test('extract prefers og:title and og:description', function () {
  var html = '<html><head><title>Fallback</title>' +
    '<meta property="og:title" content="Real Title">' +
    '<meta property="og:description" content="A description">' +
    '<meta property="og:image" content="/img/hero.png"></head><body></body></html>';
  var m = meta.extract(html, 'https://example.com/page');
  assert.equal(m.title, 'Real Title');
  assert.equal(m.description, 'A description');
  assert.equal(m.image, 'https://example.com/img/hero.png');
  assert.ok(m.icon.indexOf('example.com') >= 0);
});
test('extract falls back to <title> then host', function () {
  var m1 = meta.extract('<title>Just Title</title>', 'https://example.com/');
  assert.equal(m1.title, 'Just Title');
  var m2 = meta.extract('<html></html>', 'https://example.com/');
  assert.equal(m2.title, 'Example.com');
});
test('fallback builds host title and favicon', function () {
  var f = meta.fallback('https://www.nasa.gov/mars');
  assert.equal(f.title, 'Nasa.gov');
  assert.equal(f.description, '');
  assert.equal(f.image, '');
});
test('url helpers', function () {
  assert.equal(urls.normalize('example.com/a/'), 'https://example.com/a');
  assert.equal(urls.isValid('https://example.com/a'), true);
  assert.equal(urls.isValid('not a url'), false);
  assert.equal(urls.isValid('https://nodot'), false);
  assert.equal(urls.isPdf('https://x.com/a.pdf'), true);
  assert.equal(urls.isPdf('https://x.com/a.pdf?x=1'), true);
  assert.equal(urls.isPdf('https://x.com/a'), false);
});
